import heapq
def solution(operations):
    # Simulate MedianFinder
    # left (max_heap, negative values) and right (min_heap)
    left, right = [], []
    res = []
    for op in operations:
        cmd = op[0]
        if cmd == 'add':
            val = op[1]
            heapq.heappush(left, -val)
            # balance
            heapq.heappush(right, -heapq.heappop(left))
            if len(right) > len(left):
                heapq.heappush(left, -heapq.heappop(right))
        elif cmd == 'findMedian':
            if len(left) > len(right):
                res.append(-left[0])
            else:
                res.append((-left[0] + right[0]) / 2.0)
    return res
